\label{thm:LuoSun}
Suppose $M^n (n\ge3)$ is a closed contact stationary Legendrian  submanifold of $\mathbb{S}^{2n+1}$ and
\begin{equation*}
|B|^2\leq\dfrac{(n-1)(n+2)}{n}+\dfrac{n^2+3n-2}{2n^2}|H|^2-\dfrac{(n-1)(n-2)|H|\sqrt{4n+|H|^2}}{2n^2}.
\end{equation*}
Then $M$ is either minimal or a Calabi product Legendrian immersion of a totally geodesic Legendrian immersion and a point.

Fix an arbitrary unit vector $e_1$. The trace equations give the orthogonal
decomposition
\[
\begin{aligned}
 \sigma_{111}&=a,&\qquad \sigma_{11\beta}&=u_\beta,\\
 \sigma_{1\beta\gamma}&=-\frac{a}{n-1}\delta_{\beta\gamma}+C_{\beta\gamma},\\
 \sigma_{\beta\gamma\delta}
 &=D_{\beta\gamma\delta}
   -\frac{u_\beta\delta_{\gamma\delta}+u_\gamma\delta_{\beta\delta}
          +u_\delta\delta_{\beta\gamma}}{n+1},
\end{aligned}
\]
with $C,D$ trace-free on $e_1^\perp$. Counting the placements of the index $1$,
and using that the squared norm of the three metric insertions of $u$ is
$3(n+1)|u|^2$, gives
\begin{equation}\tag{2.1}\label{eq:2.1}
\begin{aligned}
 S&=\frac{n+2}{n-1}a^2+\frac{3(n+2)}{n+1}|u|^2+3|C|^2+|D|^2,\\
 G_{11}&=\frac{n}{n-1}a^2+2|u|^2+|C|^2.
\end{aligned}
\end{equation}
Consequently,
\[
 \alpha S-G_{11}
 =\frac{n-2}{n+1}|u|^2+\frac{2(n-1)}{n+2}|C|^2+\frac{n}{n+2}|D|^2.
\]
The nonnegative terms prove the bound and show that equality is equivalent to
$u=C=D=0$. At equality, $G_{11}=na^2/(n-1)$ and
$G_{\beta\beta}=2a^2/(n-1)^2$, so the top eigenvalue is simple. Finally,
$\operatorname{Ric}(e,e)=\alpha(c_n-S)+\alpha S-G(e,e)$.

\label{prop:sextic}
Let $\sigma$ be a trace-free symmetric cubic on $\mathbb R^n$, $n\ge3$.
For $n\ge4$, put $t=\tau_n$; for $n=3$, put $t=8/25$. Then
$\mathcal B_t\ge0$. If $S>0$ and $\mathcal B_t=0$, then
$\lambda_{\max}(G)=\alpha S$. In dimension three there is the identity
\begin{equation}\tag{2.9}\label{eq:2.9}
 \mathcal B_{8/25}=9\det\left(\tfrac35Sg-G\right).
\end{equation}
The determinant is taken after raising one index with the metric.

\label{lem:projection}
One has $z(\ell)>0$ and
\begin{equation}\tag{3.3}\label{eq:3.3}
 \mathcal B_\tau\ge\frac32p_2^2-\frac32p_3+Ap_2+C+z(\ell)r
 +\frac16|W|^2.
\end{equation}
For $\ell>1/2$, one also has
\begin{equation}\tag{3.4}\label{eq:3.4}
 \mathcal B_\tau\ge\frac32p_2^2-\frac32p_3+Ap_2+C
 +z(\ell)(2\ell-1)(L-p_2)+\frac16|W|^2.
\end{equation}

\label{lem:interpolation}
For $n\ge4$ and $1/2\le\ell\le2/3$,
\begin{equation}
 b_0(\ell)\ge\frac12(\alpha-\ell)(1-\ell).
 \tag{4.5}\label{eq:4.5}
\end{equation}
For $n=4,5,6$, the same estimate holds on $[1/2,\alpha]$.

\label{lem:opposite}
For $n\ge4$ and $1/2\le\ell\le2/3$,
\begin{equation}
 b_2(\ell)>\frac{(2\ell-1)^2}{6}.
 \tag{4.11}\label{eq:4.11}
\end{equation}

Lemma \ref{lem:interpolation} gives $b_0\ge(\alpha-\ell)(1-\ell)/2$. Since $z'<0$ and
\begin{equation}
 1-z(2/3)=\frac{2(11n^2+40n+32)}{(n+2)(n+4)(3n+8)}>0,
 \tag{4.14}\label{eq:4.14}
\end{equation}
we have $z<1$ on this interval. With $d=(n\ell-1)/(n-1)$,
\[
 M_0'=6d-2z-(2\ell-1)z'+\frac{3n}{2(n-1)}
 >\frac{7n-8}{2(n-1)}>0.
\]
At the initial point, using $z(2/3)<1$ before combining the terms gives
\begin{align*}
 M_0(2/3)&>3\bar p_2(2/3)+A-\frac13-\frac{n}{2(n-1)}\\
 &=\frac16+\frac{(6-n)(4n^2+3n-4)}{6(n-1)(n+2)(n+4)}\ge\frac16.
\end{align*}
Thus $M_0>0$, and \eqref{eq:4.2} proves the result.

\label{lem:gap}
Suppose $S=1$, $\ell>1/2$, and set
\begin{equation}
 a=\alpha\ell+\frac{2(1-\ell)}{(n-1)(n+2)},
 \qquad b=1-\ell+\frac{2(n+1)}{3(n+2)}(2\ell-1).
 \tag{5.2}\label{eq:5.2}
\end{equation}
If $\ell\ge(n+5)/(2(n+2))$, then
\begin{equation}
 |W|^2\ge9(a-p_2)(p_2-b).
 \tag{5.3}\label{eq:5.3}
\end{equation}

\label{prop:upper}
If $n\ge7$, $S=1$, and $2/3\le\ell\le\alpha$, then
$\mathcal B_{\tau_n}\ge0$.

\label{lem:axis}
Let $e$ be a smooth unit vector field on a Riemannian $n$-manifold,
and put $\xi=e^\flat$. Suppose the cubic tensor
\begin{equation}\tag{6.1}\label{eq:6.1}
 \sigma_{ijk}=\frac1{\sqrt n}
 \bigl((n+2)\xi_i\xi_j\xi_k
       -\xi_i g_{jk}-\xi_j g_{ik}-\xi_k g_{ij}\bigr)
\end{equation}
satisfies Codazzi, so that $\nabla\sigma$ is completely symmetric.
Then $\nabla e=0$ and $\nabla\sigma=0$.
